+
+std::string make_test_name(
+    const testing::TestParamInfo<GroupedRequantizeMXFP8TestSuite::ParamType> &info) {
+  const auto &test_case = std::get<0>(info.param);
+  const DType input_dtype = std::get<1>(info.param);
