+__device__ __forceinline__ uint16_t e8m0_to_bf16_bits(const e8m0_t biased_exp) {
+  if (biased_exp == 255) return 0x7fff;
+  if (biased_exp == 0) return 0x0040;
+  return static_cast<uint16_t>(biased_exp) << 7;
+}
