+                         baseline.columnwise_data.get(), actual.data_bytes);
+      expect_bytes_equal("columnwise scales", actual.columnwise_scale_inv.get(),
+                         baseline.columnwise_scale_inv.get(), actual.columnwise_scale_bytes);
+    }
